window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c8e88c841ad26e16"]={"versions": [{"id": "FIG-c8e88c841ad26e16", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (TPS Adaptive Platform Timing Extensions). Das Diagramm verortet die Kernentität <code>TimingDescriptionEvent</code> im Paket <code>M2::AUTOSARTemplates::CommonStructure::Timing::TimingDescription</code> und zeigt deren Vererbungs- und Kompositionshierarchie zur Definition von zeitlichen Ereignissen im System.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingDescription</code> (mit Stereotyp bzw. Basisklasse <code>Identifiable</code>): Übergeordnete Basiskontrakteinheit für Timing-Beschreibungen.\n</li><li><code>TimingDescriptionEvent</code>: Abstrakte Kernklasse, erbt via Generalisierung von <code>TimingDescription</code>.\n</li><li><code>TDEventOccurrenceExpression</code>: Entität zur Spezifikation von Auftretensausdrücken, eingebunden über eine gerichtete Komposition von <code>TimingDescriptionEvent</code> mit der Rollenbezeichnung <code>+occurrenceExpression</code> und der Multiplizität <code>0..1</code>.\n</li><li><code>TDEventServiceInstance</code>: Spezialisierung von <code>TimingDescriptionEvent</code> via Generalisierung zur Erfassung von servicebezogenen Ereignissen.\n</li><li><code>TDEventComplex</code>: Spezialisierung von <code>TimingDescriptionEvent</code> via Generalisierung zur Abbildung komplexer oder zusammengesetzter Timing-Ereignisse.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Nachrichtensequenzen. Zur Laufzeit bzw. während des Systembetriebs repräsentiert eine Instanz von <code>TimingDescriptionEvent</code> (konkretisiert durch <code>TDEventServiceInstance</code> oder <code>TDEventComplex</code>) das Eintreten eines beobachtbaren Ereignisses an einem definierten Systempunkt, dessen Auslöse- oder Zählbedingungen optional über die assoziierte <code>TDEventOccurrenceExpression</code> formalisiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Metamodell der Adaptive-Platform-Timing-Beschreibung gemäß AUTOSAR-Spezifikation (u. a. <code>[TPS_TIMEX_00001]</code>). Entwickler und Modellierungswerkzeuge müssen <code>TimingDescriptionEvent</code> als abstrakte Basis verwenden und spezifische Ereignisse über die abgeleiteten Klassen instanziieren. Die Kompositionsrolle <code>+occurrenceExpression</code> ist optional (Kardinalität <code>0..1</code>), womit Timing-Events auch ohne expliziten Vorkommensausdruck modellkonform sind. Alle Timing-Ereignisse sind über die Ableitung von <code>Identifiable</code> eindeutig referenzierbar.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1970c7a0d6a3f4fd", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (TPS Adaptive Platform Timing Extensions). Das Diagramm verortet die Kernentität <code>TimingDescriptionEvent</code> im Paket <code>M2::AUTOSARTemplates::CommonStructure::Timing::TimingDescription</code> und zeigt deren Vererbungs- und Kompositionshierarchie zur Definition von zeitlichen Ereignissen im System.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TimingDescription</code> (mit Stereotyp bzw. Basisklasse <code>Identifiable</code>): Übergeordnete Basiskontrakteinheit für Timing-Beschreibungen.\n</li><li><code>TimingDescriptionEvent</code>: Abstrakte Kernklasse, erbt via Generalisierung von <code>TimingDescription</code>.\n</li><li><code>TDEventOccurrenceExpression</code>: Entität zur Spezifikation von Auftretensausdrücken, eingebunden über eine gerichtete Komposition von <code>TimingDescriptionEvent</code> mit der Rollenbezeichnung <code>+occurrenceExpression</code> und der Multiplizität <code>0..1</code>.\n</li><li><code>TDEventServiceInstance</code>: Spezialisierung von <code>TimingDescriptionEvent</code> via Generalisierung zur Erfassung von servicebezogenen Ereignissen.\n</li><li><code>TDEventComplex</code>: Spezialisierung von <code>TimingDescriptionEvent</code> via Generalisierung zur Abbildung komplexer oder zusammengesetzter Timing-Ereignisse.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Ablauf- oder Nachrichtensequenzen. Zur Laufzeit bzw. während des Systembetriebs repräsentiert eine Instanz von <code>TimingDescriptionEvent</code> (konkretisiert durch <code>TDEventServiceInstance</code> oder <code>TDEventComplex</code>) das Eintreten eines beobachtbaren Ereignisses an einem definierten Systempunkt, dessen Auslöse- oder Zählbedingungen optional über die assoziierte <code>TDEventOccurrenceExpression</code> formalisiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für das Metamodell der Adaptive-Platform-Timing-Beschreibung gemäß AUTOSAR-Spezifikation (u. a. <code>[TPS_TIMEX_00001]</code>). Entwickler und Modellierungswerkzeuge müssen <code>TimingDescriptionEvent</code> als abstrakte Basis verwenden und spezifische Ereignisse über die abgeleiteten Klassen instanziieren. Die Kompositionsrolle <code>+occurrenceExpression</code> ist optional (Kardinalität <code>0..1</code>), womit Timing-Events auch ohne expliziten Vorkommensausdruck modellkonform sind. Alle Timing-Ereignisse sind über die Ableitung von <code>Identifiable</code> eindeutig referenzierbar.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c8e88c841ad26e16", "to": "FIG-1970c7a0d6a3f4fd", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
